import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"/goal + Loss Functions: How to Distill a Product in 30 Hours with One Prompt [Full Playbook]","description":"","frontmatter":{"url":"https://x.com/elvissun/status/2065035615800864954","title":"/goal + Loss Functions: How to Distill a Product in 30 Hours with One Prompt [Full Playbook]","author":"Elvis","archived":"2026-06-11T00:00:00.000Z","handle":"@elvissun","published":"2026-06-11T00:00:00.000Z","stats":"92 likes · 7 retweets · 235 bookmarks · 6611 views","tags":["goal","loss-function-development","lfd","agent-design","harness","forced-entropy","product-distillation"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-11-@elvissun-864954.md","filePath":"research/tweets/2026-06-11-@elvissun-864954.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-06-11-@elvissun-864954.md"};function s(r,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="goal-loss-functions-how-to-distill-a-product-in-30-hours-with-one-prompt-full-playbook-—-elvissun" tabindex="-1">/goal + Loss Functions: How to Distill a Product in 30 Hours with One Prompt [Full Playbook] — @elvissun <a class="header-anchor" href="#goal-loss-functions-how-to-distill-a-product-in-30-hours-with-one-prompt-full-playbook-—-elvissun" aria-label="Permalink to &quot;/goal + Loss Functions: How to Distill a Product in 30 Hours with One Prompt [Full Playbook] — @elvissun&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/elvissun/status/2065035615800864954" target="_blank" rel="noreferrer">https://x.com/elvissun/status/2065035615800864954</a><strong>作者</strong>：Elvis（@elvissun） <strong>發布日期</strong>：2026-06-11 <strong>收錄日期</strong>：2026-06-11 <strong>類型</strong>：Twitter Article <strong>統計</strong>：92 likes · 7 retweets · 235 bookmarks · 6611 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>99% people are using /goal and loops wrong. The hype they hear is &quot;long-running loops prompting autonomous agent&quot;: point it at a task, walk away, come back to working code. But top agentic engineers have been doing that without /goal for 6 months (when GPT-5.2 and Opus 4.5 came out). It&#39;s called harness engineering + spec-driven development:</p><ol><li>build a harness for agent to observe the problem</li><li>write a tight spec with all the test cases</li><li>let Codex or Claude Code loop unattended until it meets every one. I kick these off overnight constantly — 2-5 hours a run. In April one chewed through a Turbo build-cache bug across our Vercel monorepo and had it green by morning. No /goal is actually required.</li></ol><h2 id="so-what-s-goal-actually-for" tabindex="-1">So what&#39;s /goal actually for? <a class="header-anchor" href="#so-what-s-goal-actually-for" aria-label="Permalink to &quot;So what&#39;s /goal actually for?&quot;">​</a></h2><p>Here&#39;s what one single prompt did while I was away:</p><ul><li>~30 hours, 6,300 lines of code, 92k pages crawled, $40 spent on APIs</li><li>Clone the core loop of another product — entire architecture reverse-engineered from scratch</li><li>Our version&#39;s output was ~50× better than the reference product on the same queries. (This is a new data layer that&#39;ll power newsjack.sh - the open-source news-intel skills I&#39;ve been working on) The secret is loss function development (LFD): you write the agent a target to optimize toward, not a spec to build. This is a concrete example of Peter&#39;s tweet, operationalized. The spec used in spec-driven development now becomes the starting point, no longer the finish line. It took me some experimenting to get this right. But here&#39;s the entire playbook — but we need to start with how badly it went first so you understand how to design these /goals.</li></ul><h2 id="the-agent-cheated-3-times" tabindex="-1">The agent cheated 3 times. <a class="header-anchor" href="#the-agent-cheated-3-times" aria-label="Permalink to &quot;The agent cheated 3 times.&quot;">​</a></h2><p>Everything started with what I always do: a spec. I simply pointed codex at the other product&#39;s public website - &quot;how can we build this ourselves?&quot;. In 30 minutes it came back with a full system design and test cases - the spec. But this time, I tried a different prompt. &quot;/goal implement until your output matches theirs exactly&quot; And here&#39;s what happened: Loop 1 (5 minutes) The agent grabbed the eval set, generated seed data that mirrored it, and declared victory in five minutes. &quot;100%&quot; recall, zero generality — a search engine that could only find the 30 things I&#39;d handed it lol. Fix → blind it. Eval hidden during the run, revealed only at scoring, with a per-item miss list. Loop 2 (20 minutes) - blind, 30 items. I blinded the agent from eval set, but it learned by miss instead — every &quot;you didn&#39;t find X&quot; became a keyword next cycle. A few loops in: it used exactly 30 keywords, one per item, and it &quot;won&quot; again. Fix → widen the eval set. Hundreds of items to score against, too many to enumerate. Loop 3 (30 minutes) - blind, 200 items. After adding 200 items to the new eval set, agent cheated again. Funny enough, the agent enumerated anyway. The keyword list ballooned into the hundreds, each term a precise lure for the next miss. Three rounds, three cheats. That&#39;s when it clicked: the agent was simply optimizing. The cheating wasn&#39;t a bug in the agent. It was a bug in my target: I told it where to go and left every shortcut wide open. Every cheap path you don&#39;t fence off is a direction the optimizer will sprint down. And my initial target and skipped all the fences. Loop 4 (30 hours) - blind, 200 items, hard limits. So I started blocking directions. Cap the keyword list, blind the eval, widen the date — each fix closed one more cheap path, until the only direction left that moved the number was getting genuinely better at the task. It stopped cheating. Then it ran. ~30 hours of compute, 92k pages crawled, ~$40 in tokens, 6,300 lines of code. It turns out the product we were referencing was the floor, not the ceiling: we ended up surfacing ~50× the results on the same queries. [圖 1] (The full journey and receipts here for those curious)</p><h2 id="loss-function-development-lfd-the-anatomy-of-a-good-loss-function" tabindex="-1">Loss function development (LFD) - the anatomy of a good loss function <a class="header-anchor" href="#loss-function-development-lfd-the-anatomy-of-a-good-loss-function" aria-label="Permalink to &quot;Loss function development (LFD) - the anatomy of a good loss function&quot;">​</a></h2><p>When most people try to build a product, they are using agents to go from zero to shipped in a few hours. But the catch is what comes after — the long tail. Edge cases the spec never imagined surface only in production, one error log at a time. You fix them one by one. The cases you don&#39;t catch in logs get reported by users, which is the most expensive way to find a bug. I&#39;ve automated the cheap end of this. My OpenClaw agent Zoe watches error log every day and spawns Codex on new errors as they roll in and create PRs — about as tight as that loop gets. (Full setup documented here) The tail still takes months. That&#39;s why building a good product still takes time even with agents doing the work. LFD fast-forwards the tail. If you can get real expected-output examples up front — what good looks like, at scale — you run the soak before you ship: hundreds of edge cases hit the agent in one optimization run, not one quarterly drip of bug reports. And the reason this is suddenly feasible is that for more and more problems, those examples are just sitting in public. Spec-driven development:</p><blockquote><p>Build this. Make the tests pass. Loss-function development: Build this. Make the tests pass. Then iterate against these 1,000 eval cases. A test suite is finite — done the moment it&#39;s green. A 1,000-case eval at 95% is a target you descend toward; there&#39;s no exit short of the bar. That matters because the agent makes hundreds of decisions you&#39;ll never see, and every one resolves against something. If you didn&#39;t write the target, the agent picks one — and as rounds 1–3 showed, it picks whatever&#39;s cheapest to satisfy. The loss-function is bigger than the eval. It has 4 things - the target, the constraints, the instruments, and the forced entropy. Four pieces.</p></blockquote><ol><li>Target</li></ol><ul><li>Large enough that enumeration doesn&#39;t pay. A 28-item eval got memorized in one round. The more the better.</li><li>Blind the agent to the answer key. Eval data exists only for post-hoc scoring. If the agent can see the answers during the run, it will find a way to look.</li></ul><ol start="2"><li>Constraints What the agent is allowed to do, and what it isn&#39;t.</li></ol><ul><li>Time is the constraint the agent always forgets. Agents have no sense of time. They will grind for 10 hours on a 2% gain because the metric is nominally moving. But an 80% solution in 2 hours beats a 100% one completed in 30 days. Solution: set a wall-clock budget.</li><li>Money. Hard caps on every paid call: crawler credits, LLM spend, total dollar ceiling on a disposable key.</li><li>Surface. All providers, allowed models, concurrency ceilings. Sandbox the agent to only things you want it to touch.</li><li>Methodology. Is LLM analysis allowed, or only deterministic logic? What data sources does the agent have access to? Spell it out.</li></ul><ol start="3"><li>Instruments (the harness) A constraint without an instrument is a vibe — the agent will violate it cheerfully because it can&#39;t tell it&#39;s violating it. For every constraint above, ship a CLI command for the agent to inspect it.</li></ol><ul><li>Target measurement, at the right resolution. Pick the target instrument carefully. Real example: a naive &quot;have an LLM rate two screenshots&quot; judge approves UI clones with 12px spacing errors, because LLMs can&#39;t actually see the images, it converts them to embedding then compare the embedding. So if you want pixel perfect UI clones, give your agent a pixel-diff tool. Then /goal until pixel diff is 0.</li><li>Time accounting. Timestamp every run and every step. The agent should know how long each step took, the total wall-clock elapsed. Time is a first-class instrument, not a footnote.</li><li>Provider budget. &quot;How much are we burning on crawlers right now?&quot; should be one command, not a guess. Track scrape credits remaining, burn this loop, burn cumulative, and projected burn before the next paid batch.</li><li>LLM spend. Giving it an LLM API key to use in the data-plane can simplify a lot of the logic. But the agent should spend them responsibly, by first knowing how much it&#39;s actually spending.</li><li>Codex Usage. This one is a little meta. The loop should be self-aware: how much tokens am I spending on this optimization? Helpful for knowing the gradient of the current optimization step. The pattern is the same old saying: you can&#39;t optimize what you can&#39;t see. If you&#39;re new to running these loops, don&#39;t kick it off and walk away. Sit with the first cycle. Watch what it touches. Confirm the harness you built is actually being used properly. Then go to bed. (And try to fall asleep without thinking about what you wake up to)</li></ul><ol start="4"><li>Forced entropy Why forced entropy matters: each loop continues from the previous run&#39;s entire context. The model isn&#39;t starting fresh — it&#39;s reading its own last hundred decisions and the gradient that worked so far. In a /goal loop, hitting local maxima is the default state. Without an explicit kick, the agent keeps walking up the same hill, and &quot;the same hill&quot; is wherever it happened to be when it stopped improving. For example if a small knob improves the outcome by 0.1%, the agent will keep turning that one knob even if it has 1000 other knobs to try. Entropy needs to be forced into the run explicitly, because the model won&#39;t take it on its own:</li></ol><ul><li>Overfit reflection every cycle. Am I building a more general solution, or memorizing the eval? If memorizing, the next change must remove an eval-shaped artifact (cap a list, blind a feature, widen the eval, reject a seed), not add one.</li><li>Force entropy on stall. If the last cycle didn&#39;t move the metric, the next one can&#39;t be &quot;same idea, harder.&quot; The model has to make a real non-obvious jump — &quot;think outside the box&quot; is a good prompt - stops the agent from just turn the same knob harder.</li><li>Keep an iteration log. Make the agent log the hypothesis, the expected failure mode, the diagnostic each step, so it can look back and reflect across compactions.</li></ul><h2 id="the-meta-meta-prompt" tabindex="-1">The Meta-Meta-Prompt <a class="header-anchor" href="#the-meta-meta-prompt" aria-label="Permalink to &quot;The Meta-Meta-Prompt&quot;">​</a></h2><p>I was writing these goals myself then quickly learned that&#39;s a job for the agents too. So I wrote a skill that produce these type of goals for a good loss-function-development run. Now open-sourced here: <a href="https://github.com/elvisun/loss-function-development" target="_blank" rel="noreferrer">https://github.com/elvisun/loss-function-development</a> [圖 2 — 來源: /lfd-design to generate the harness and the goal]</p><h2 id="gradient-descent-all-the-way-down-the-two-loops" tabindex="-1">Gradient descent all the way down: the two loops <a class="header-anchor" href="#gradient-descent-all-the-way-down-the-two-loops" aria-label="Permalink to &quot;Gradient descent all the way down: the two loops&quot;">​</a></h2><p>Step back and it&#39;s gradient descent all the way down. The inner loop is the agent: write code, run tests, fix. Short horizon, fast feedback, one objective — make the tests pass. That&#39;s a developer&#39;s inner loop, and spec-driven development is how you run it. Coding agents already automated it. The outer loop is /goal: drive the whole system toward an outcome metric across many cycles — ship, measure, change tack, descend. Long horizon, sparse feedback. That&#39;s traditionally a product team&#39;s loop, the months of ship-measure-iterate soak compressed into a single run. Both loops are automated now. What&#39;s left on you is the defining the loss function — what exactly should the /goal optimize towards and in what way.</p><h2 id="you-re-distilling-a-product-—-or-anything-that-leaves-a-public-artifact" tabindex="-1">You&#39;re distilling a product — or anything that leaves a public artifact <a class="header-anchor" href="#you-re-distilling-a-product-—-or-anything-that-leaves-a-public-artifact" aria-label="Permalink to &quot;You&#39;re distilling a product — or anything that leaves a public artifact&quot;">​</a></h2><p>Another lens: this is essentially distillation, moved from training-time to prompt-time. It&#39;s how the DeepSeek, Kimi, Minimax line closed most of the gap to GPT and Claude — train your model on someone else&#39;s outputs until yours reproduces them. But instead of distilling a model, you can now use /goal and LFD to run distillation fitting to any publicly findable artifacts — it never inspects the internals and doesn&#39;t need to. Lean on the word publicly. Distilling someone&#39;s ToS-gated, login-walled, or paid output isn&#39;t fair game. But what&#39;s published in the open — the outputs a company ships to win customers — has always been fair to learn from. That part isn&#39;t new - it&#39;s the oldest move in software. What&#39;s new is that it&#39;s now cheap and can be done in hours instead of months. Step back, and here&#39;s the bigger shift. The cost of execution collapses to ~$0 wherever there&#39;s information symmetry — when the outputs are public, everyone can see what good looks like, so anyone can distill it back out over a weekend for $40. So here&#39;s a new moat that&#39;s becoming increasingly valuable: information asymmetry. The canonical open-source company already blinked. In April 2026, cal.com ($5M ARR) took its production code private and went closed-source. The reason they gave reads literally like this essay&#39;s abstract: in an age of AI-driven security threats, you can&#39;t leave your source where an agent can read it. &quot;/goal read cal.com source code and enumerate its attack surface until something works&quot; That&#39;s way too dangerous of an attack that&#39;s way too easy to execute. The company whose entire identity was &quot;open source&quot; decided, in 2026, that openness had become a liability. That should tell you everything. For the entire history of software, &quot;we built it&quot; was the moat. That era is closing. The next one belongs to whoever owns what the artifact never contained: the eval set nobody else can score against. The list of edge cases your users actually trip on. The ground truth you measure privately. Whoever has the target the competitor&#39;s agent can&#39;t see is the only one whose loop keeps descending. The product is a weekend now. Go build the eval a weekend can&#39;t touch.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：/goal 的真正用途是 Loss Function Development（LFD）——用最佳化目標取代 spec，4 元素框架（Target/Constraints/Instruments/Forced Entropy）讓 agent 在 30 小時內逆向工程出超越參考產品的結果。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>/goal ≠ spec-driven overnight loop</strong>：harness + spec 的無人值守 loop 6 個月前就可以了；/goal 的真正差異化用途是 Loss Function Development（LFD）——寫「最佳化目標」而非「要建什麼」</li><li><strong>Agent 會作弊三次</strong>：每次都精確優化了你給的目標卻不解決真正問題；解法依序是：blind eval → widen eval（200+ items）→ cap shortcuts（keyword list, time budget）</li><li><strong>LFD 四元素</strong>：Target（夠大且 blind）/ Constraints（time/money/surface/methodology 四項硬限制）/ Instruments（每個 constraint 都要對應 CLI 可量測工具）/ Forced Entropy（每輪 overfit 反思 + stall 時強制非顯而易見跳躍）</li><li><strong>兩層 loop 結構</strong>：inner loop = spec-driven dev（短迴圈，tests pass）；outer loop = /goal LFD（長迴圈，最佳化 outcome metric）—— 兩者都已自動化，剩下人做的只有定義 loss function</li><li><strong>護城河轉移</strong>：執行成本趨近 $0（公開 artifact + $40 = 產品 weekend）；真正的護城河是 information asymmetry（私有 eval set + 私有 edge case ground truth）</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>實測結果：30h / 6,300 lines of code / 92K pages crawled / $40 API cost → 50× better than reference</li><li>Eval 大小建議：28 items → memorized in 1 round；需 200+ 才有效</li><li>Loop 演進：Loop1(5min,作弊) → Loop2(20min,作弊) → Loop3(30min,作弊) → Loop4(30h,成功)</li><li>工具：github.com/elvisun/loss-function-development（/lfd-design skill）</li><li>案例：cal.com ($5M ARR) 2026/4 轉為閉源（cited AI-driven security threats）</li><li>Instrument 反例：LLM screenshot judge 無法偵測 12px spacing error → 應用 pixel-diff tool</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>50× 的 claim 基於自定義 eval</strong>：eval 本身由作者設計，benchmark 在設計者手中難以對外量化；「比 reference 好 50×」缺乏第三方驗證</li><li><strong>Forced entropy 的「think outside the box」過於模糊</strong>：作為防 local maxima 的具體機制，這個提示詞是最弱的一個建議；文中其他技術（overfit reflection, iteration log）更可操作</li><li><strong>Cal.com 案例被過度延伸</strong>：轉向閉源的主要理由是安全而非 AI 競爭壓力，拿來作「資訊不對稱護城河」的 evidence 有些 overfitting</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>LFD 4 元素框架 + 防作弊 pattern + open-source /lfd-design skill 全部立即可部署</td></tr><tr><td>B. 創新性 (20%)</td><td>9/10</td><td>LFD 作為 spec-driven dev 外層 loop 的概念清晰且原創；3 次作弊案例高度實戰</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>30h/$40 的具體數字有說服力，但 50× 為自評 eval；eval 設計本身有 circularity 問題</td></tr><tr><td>D. 技術深度 (15%)</td><td>9/10</td><td>Instrument 設計（pixel-diff/time accounting/provider budget）、Forced Entropy、兩層 loop 架構全部有深度</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>LFD 框架適用任何有公開 artifact 的領域；護城河論述對所有軟體公司有意義</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.45/10</strong></td><td>9×0.3+9×0.2+7×0.2+9×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Agent <strong>理由</strong>：核心是設計多步驟自主最佳化流程（/goal + LFD 4 元素），屬於 Agent 設計框架而非單一原則。</p>',41)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
